// Inyectado por vite.config.ts (define) a partir de package.json#version.
declare const __APP_VERSION__: string;

// Inyectado por vite.config.ts (define): hash corto del commit del build
// actual — permite distinguir deploys de una misma versión (ej. la rama
// post-v1-ux, que no sube de versión en cada push).
declare const __BUILD_ID__: string;
